<?php
session_start();require_once 'db.php';
if(!isset($_SESSION['user_id'])){header('Location: login.html');exit;}
$userId=(int)$_SESSION['user_id'];$role=$_SESSION['role'];$name=htmlspecialchars($_SESSION['full_name'],ENT_QUOTES,'UTF-8');
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function statusClass($s){return strtolower(str_replace([' ','_'],'-',(string)$s));}
function statusBadge($s){return '<span class="status-badge '.h(statusClass($s)).'">'.h($s).'</span>';}
$tech=null;$bookings=[];$pendingTech=[];$allCounts=[];$technicianReviews=[];
if($role==='technician'){
 $q=$conn->prepare('SELECT * FROM technicians WHERE user_id=?');$q->bind_param('i',$userId);$q->execute();$tech=$q->get_result()->fetch_assoc();$q->close();
 if($tech){$q=$conn->prepare('SELECT b.*,u.full_name customer_name,u.phone customer_phone FROM bookings b JOIN users u ON u.id=b.user_id WHERE b.technician_id=? ORDER BY FIELD(b.status,\'Requested\',\'Accepted\',\'On the Way\',\'In Progress\',\'Completed\',\'Rejected\',\'Cancelled\'),b.created_at DESC');$q->bind_param('i',$tech['id']);$q->execute();$bookings=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();}
 if($tech){$rq=$conn->prepare("SELECT rr.stars,rr.comment,rr.created_at,u.full_name customer_name,b.booking_code FROM ratings_reviews rr JOIN users u ON u.id=rr.customer_id JOIN bookings b ON b.id=rr.booking_id WHERE rr.technician_id=? AND rr.review_status='visible' ORDER BY rr.created_at DESC");$rq->bind_param('i',$tech['id']);$rq->execute();$technicianReviews=$rq->get_result()->fetch_all(MYSQLI_ASSOC);$rq->close();}
}elseif($role==='customer'){
 $q=$conn->prepare('SELECT b.*,COALESCE(tu.full_name,b.technician_name) assigned_technician,(SELECT p.id FROM payments p WHERE p.booking_id=b.id AND p.payment_status=\'success\' ORDER BY p.id DESC LIMIT 1) payment_id,(SELECT rr.id FROM ratings_reviews rr WHERE rr.booking_id=b.id) review_id,(SELECT rr.stars FROM ratings_reviews rr WHERE rr.booking_id=b.id) review_stars,(SELECT rr.comment FROM ratings_reviews rr WHERE rr.booking_id=b.id) review_comment FROM bookings b LEFT JOIN technicians t ON t.id=b.technician_id LEFT JOIN users tu ON tu.id=t.user_id WHERE b.user_id=? ORDER BY b.created_at DESC');$q->bind_param('i',$userId);$q->execute();$bookings=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();
}elseif($role==='admin'){
 $pendingTech=$conn->query("SELECT t.id,t.professional_title,t.experience_years,t.service_areas,t.verification_status,u.full_name,u.email,u.phone,vd.id document_id,vd.document_type,vd.uploaded_at FROM technicians t JOIN users u ON u.id=t.user_id LEFT JOIN verification_documents vd ON vd.technician_id=t.id AND vd.review_status IN ('pending','resubmit') WHERE t.verification_status IN ('pending','resubmission_required') ORDER BY t.created_at ASC")->fetch_all(MYSQLI_ASSOC);
 $allCounts=['users'=>(int)$conn->query('SELECT COUNT(*) c FROM users')->fetch_assoc()['c'],'technicians'=>(int)$conn->query('SELECT COUNT(*) c FROM technicians')->fetch_assoc()['c'],'bookings'=>(int)$conn->query('SELECT COUNT(*) c FROM bookings')->fetch_assoc()['c'],'pending'=>(int)$conn->query("SELECT COUNT(*) c FROM technicians WHERE verification_status IN ('pending','resubmission_required')")->fetch_assoc()['c']];
 $allUsers=$conn->query("SELECT id,full_name,email,phone,role,account_status,created_at FROM users ORDER BY created_at DESC")->fetch_all(MYSQLI_ASSOC);
 $allBookings=$conn->query("SELECT b.id,b.booking_code,b.category,b.subcategory,b.location,b.booking_date,b.booking_time,b.status,u.full_name customer_name,COALESCE(tu.full_name,b.technician_name) technician_name FROM bookings b JOIN users u ON u.id=b.user_id LEFT JOIN technicians t ON t.id=b.technician_id LEFT JOIN users tu ON tu.id=t.user_id ORDER BY b.created_at DESC")->fetch_all(MYSQLI_ASSOC);
}
?>
