 <?php if($tech['verification_status']!=='approved'):?><div class="workflow-alert">Your profile is waiting for admin approval. You cannot receive or accept jobs until your documents are approved.</div><?php else:?><form class="workflow-form" method="post" action="technician_availability.php"><label for="availability">Job availability</label><select id="availability" name="availability"><option value="available" <?php echo $tech['available_status']==='available'?'selected':'';?>>Available</option><option value="unavailable" <?php echo $tech['available_status']==='unavailable'?'selected':'';?>>Unavailable</option></select><button class="btn btn-primary btn-sm" type="submit">Save Availability</button></form><?php endif;?></div>
 <div class="workflow-grid"><div class="workflow-card"><span class="workflow-muted">Assigned jobs</span><h3><?php echo count($bookings);?></h3></div><div class="workflow-card"><span class="workflow-muted">Pending requests</span><h3><?php echo count(array_filter($bookings,fn($b)=>$b['status']==='Requested'));?></h3></div><div class="workflow-card"><span class="workflow-muted">Completed jobs</span><h3><?php echo (int)$tech['completed_jobs'];?></h3></div><div class="workflow-card"><span class="workflow-muted">Average rating</span><h3><?php echo number_format((float)$tech['average_rating'],1);?> / 5</h3><small class="workflow-muted"><?php echo (int)$tech['total_reviews'];?> customer reviews</small></div></div>
 <div class="workflow-panel"><h2>My Job Requests & Jobs</h2><p class="workflow-muted">Only bookings assigned to your technician profile are shown here. Customer contact details are revealed after you accept a request.</p><div class="workflow-scroll"><table class="workflow-table"><thead><tr><th>Booking / Customer</th><th>Service details</th><th>Location & Schedule</th><th>Status</th><th>Actions</th></tr></thead><tbody>
 <?php if(!$bookings):?><tr><td colspan="5" class="workflow-empty">No jobs assigned yet. Keep your availability set to Available after approval.</td></tr><?php else:foreach($bookings as $b):?><tr><td><strong><?php echo h($b['booking_code']?:('#'.$b['id']));?></strong><br><?php echo h($b['customer_name']);?><?php if(in_array($b['status'],['Accepted','On the Way','In Progress','Completed'],true)):?><br><small><?php echo h($b['customer_phone']);?></small><?php else:?><br><small class="workflow-muted">Contact details hidden until accepted</small><?php endif;?></td><td><?php echo h($b['category'].' / '.$b['subcategory']);?><br><small><?php echo h($b['description']);?></small></td><td><?php echo h($b['location']);?><br><?php echo h($b['booking_date'].' '.$b['booking_time']);?></td><td><?php echo statusBadge($b['status']);?></td><td><div class="workflow-actions"><?php if($b['status']==='Requested'):?><form method="post" action="update_booking.php" class="workflow-form"><input type="hidden" name="booking_id" value="<?php echo (int)$b['id'];?>"><input type="number" name="final_price" min="1" step="0.01" placeholder="Service charge (BDT)" required style="width:150px"><button class="btn btn-primary btn-sm" name="action" value="accept">Accept & Set Price</button></form><form method="post" action="update_booking.php" onsubmit="return confirm('Reject this job request?')"><input type="hidden" name="booking_id" value="<?php echo (int)$b['id'];?>"><button class="btn btn-outline btn-sm" name="action" value="reject">Reject</button></form><?php elseif(in_array($b['status'],['Accepted','On the Way','In Progress'],true)):$next=$b['status']==='Accepted'?'On the Way':($b['status']==='On the Way'?'In Progress':'Completed');?><form method="post" action="update_booking.php"><input type="hidden" name="booking_id" value="<?php echo (int)$b['id'];?>"><input type="hidden" name="action" value="progress"><input type="hidden" name="status" value="<?php echo h($next);?>"><button class="btn btn-primary btn-sm" type="submit">Mark <?php echo h($next);?></button></form><?php else:?><span class="workflow-muted">No action available</span><?php endif;?></div></td></tr><?php endforeach;endif;?>
 </tbody></table></div></div>
<div class="workflow-panel"><h2>Customer Reviews</h2><p class="workflow-muted">Reviews submitted by customers after completed jobs.</p><?php if(!$technicianReviews):?><p class="workflow-empty">No customer reviews yet.</p><?php else:foreach($technicianReviews as $review):?><div style="padding:14px 0;border-bottom:1px solid #eee"><strong><?php echo h($review['customer_name']);?></strong> <span style="color:#d69e00"><?php echo str_repeat('★',(int)$review['stars']).str_repeat('☆',5-(int)$review['stars']);?></span><small class="workflow-muted"> · <?php echo h($review['created_at']);?></small><?php if($review['comment']):?><p style="margin:8px 0 0"><?php echo nl2br(h($review['comment']));?></p><?php endif;?></div><?php endforeach;endif;?></div>
