 <div class="workflow-panel"><h2>Technician Verification Queue</h2><p class="workflow-muted">Review the submitted document before approving or rejecting a technician.</p><div class="workflow-scroll"><table class="workflow-table"><thead><tr><th>Technician</th><th>Professional details</th><th>Document</th><th>Review decision</th></tr></thead><tbody><?php if(!$pendingTech):?><tr><td colspan="4" class="workflow-empty">No technicians are waiting for verification.</td></tr><?php else:foreach($pendingTech as $p):?><tr><td><strong><?php echo h($p['full_name']);?></strong><br><?php echo h($p['email']);?><br><?php echo h($p['phone']);?></td><td><?php echo h($p['professional_title']);?><br><?php echo (int)$p['experience_years'];?> years experience<br><small><?php echo h($p['service_areas']);?></small><br><?php echo statusBadge(ucwords(str_replace('_',' ',$p['verification_status'])));?></td><td><?php if($p['document_id']):?><a class="workflow-doc" target="_blank" rel="noopener" href="view_verification_document.php?id=<?php echo (int)$p['document_id'];?>">View <?php echo h($p['document_type']);?></a><?php else:?>No pending document<?php endif;?></td><td><form method="post" action="admin_review_technician.php"><input type="hidden" name="technician_id" value="<?php echo (int)$p['id'];?>"><textarea name="admin_note" rows="2" placeholder="Optional note"></textarea><div class="workflow-actions" style="margin-top:8px"><button class="btn btn-primary btn-sm" name="decision" value="approved">Approve</button><button class="btn btn-outline btn-sm" name="decision" value="rejected">Reject</button><button class="btn btn-outline btn-sm" name="decision" value="resubmission_required">Request Resubmission</button></div></form></td></tr><?php endforeach;endif;?></tbody></table></div></div>
<div class="workflow-panel"><h2>Manage All Users</h2><p class="workflow-muted">View registered accounts and activate, deactivate or block accounts. Your own administrator account cannot be blocked here.</p><div class="workflow-scroll"><table class="workflow-table"><thead><tr><th>User</th><th>Contact</th><th>Role</th><th>Account status</th><th>Action</th></tr></thead><tbody><?php foreach($allUsers as $u):?><tr><td><?php echo h($u['full_name']);?><br><small>#<?php echo (int)$u['id'];?></small></td><td><?php echo h($u['email']);?><br><?php echo h($u['phone']);?></td><td><?php echo h(ucfirst($u['role']));?></td><td><?php echo statusBadge(ucfirst($u['account_status']));?></td><td><?php if((int)$u['id']!==$userId):?><form method="post" action="admin_manage.php" class="workflow-form"><input type="hidden" name="type" value="user"><input type="hidden" name="user_id" value="<?php echo (int)$u['id'];?>"><select name="account_status"><option value="active" <?php echo $u['account_status']==='active'?'selected':'';?>>Active</option><option value="inactive" <?php echo $u['account_status']==='inactive'?'selected':'';?>>Inactive</option><option value="blocked" <?php echo $u['account_status']==='blocked'?'selected':'';?>>Blocked</option></select><button class="btn btn-primary btn-sm">Save</button></form><?php else:?>Current account<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
