--):?><option value="<?php echo $star;?>"><?php echo $star;?> Star<?php echo $star>1?'s':'';?></option><?php endfor;?></select><textarea name="comment" rows="2" maxlength="1000" placeholder="Write your comment (optional)" style="width:100%;padding:8px"></textarea><button class="btn btn-primary btn-sm" type="submit" style="margin-top:6px">Submit Review</button></form><?php else:?><br><small class="workflow-muted">Your review: <?php echo (int)$b['review_stars'];?> / 5 stars</small><?php if($b['review_comment']):?><br><small><?php echo h($b['review_comment']);?></small><?php endif;?><?php endif;?><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div>
